
const LAND_B64="";

const N = 1536;
const TAU = Math.PI * 2;
const DEG = 180 / Math.PI;
const RAD = Math.PI / 180;
const ANG = Math.sqrt(4 * Math.PI / N) * 0.36;
const SEGS = 48;
const MERC_MAX = 85.05113 * RAD;
const META = {
  globe: {
    index: "01", name: "Globe", claim: "Surface kept",
    note: "The sphere is the reference surface. This globe view is an orthographic projection: equal disks foreshorten toward its rim.",
    plateTitle: "Fig. 01 — map area scales", plateKey: "local area ×",
    plateCaption: "Local area scale: Mercator and Equal Earth.", plateSide: "unit sphere"
  },
  mercator: {
    index: "02", name: "Mercator", claim: "Conformal claim",
    note: "Local angles are preserved. Area scale grows away from the equator. The polar caps are outside this map.",
    plateTitle: "Fig. 02 — map area scales", plateKey: "sec² φ · 1",
    plateCaption: "Local area scale versus latitude.", plateSide: "cylindrical"
  },
  equalearth: {
    index: "03", name: "Equal Earth", claim: "Area claim",
    note: "Šavrič, Jenny & Patterson, 2018. Area is held. Shape is spent toward the sides — continents keep their relative size.",
    plateTitle: "Fig. 03 — map area scales", plateKey: "sec² φ · 1",
    plateCaption: "Equal Earth has unit local area scale.", plateSide: "Equal Earth"
  }
};

const landBytes = Uint8Array.from(atob(LAND_B64), c => c.charCodeAt(0));
function isLand(lon, lat) {
  const x = ((Math.round((lon + Math.PI) / TAU * 360) % 360) + 360) % 360;
  const y = Math.min(179, Math.max(0, Math.round((Math.PI / 2 - lat) / Math.PI * 180)));
  const i = y * 360 + x;
  return (landBytes[i >> 3] >> (7 - (i & 7))) & 1;
}

function fibonacci(n) {
  const g = Math.PI * (3 - Math.sqrt(5));
  const pts = new Array(n);
  for (let i = 0; i < n; i++) {
    const y = 1 - (i + 0.5) / n * 2;
    const r = Math.sqrt(Math.max(0, 1 - y * y));
    const t = g * i;
    const x = Math.cos(t) * r;
    const z = Math.sin(t) * r;
    const lat = Math.asin(Math.max(-1, Math.min(1, y)));
    const lon = Math.atan2(z, x);
    pts[i] = { i, x, y, z, lat, lon, land: isLand(lon, lat) };
  }
  return pts;
}

function basis(lat, lon) {
  const cl = Math.cos(lat), sl = Math.sin(lat), co = Math.cos(lon), so = Math.sin(lon);
  const c = [cl * co, sl, cl * so];
  const e = [-so, 0, co];
  const n = [-sl * co, cl, -sl * so];
  return { c, e, n };
}

function disk(lat, lon, rad, segs) {
  const { c, e, n } = basis(lat, lon);
  const cr = Math.cos(rad), sr = Math.sin(rad);
  const out = new Array(segs);
  for (let k = 0; k < segs; k++) {
    const a = k / segs * TAU;
    const ca = Math.cos(a), sa = Math.sin(a);
    const x = c[0] * cr + (e[0] * ca + n[0] * sa) * sr;
    const y = c[1] * cr + (e[1] * ca + n[1] * sa) * sr;
    const z = c[2] * cr + (e[2] * ca + n[2] * sa) * sr;
    out[k] = { lat: Math.asin(Math.max(-1, Math.min(1, y))), lon: Math.atan2(z, x) };
  }
  return out;
}

function wrapPi(a) {
  return Math.atan2(Math.sin(a), Math.cos(a));
}

function mercatorXY(lon, lat) {
  const φ = Math.max(-MERC_MAX, Math.min(MERC_MAX, lat));
  return [lon, Math.log(Math.tan(Math.PI / 4 + φ / 2))];
}

const EE_A1 = 1.340264, EE_A2 = -0.081106, EE_A3 = 0.000893, EE_A4 = 0.003796;
const EE_M = Math.sqrt(3) / 2;

function equalEarthXY(lon, lat) {
  const theta = Math.asin(Math.max(-1, Math.min(1, EE_M * Math.sin(lat))));
  const t2 = theta * theta;
  const t6 = t2 * t2 * t2;
  const polyY = EE_A1 + EE_A2 * t2 + t6 * (EE_A3 + EE_A4 * t2);
  const polyX = EE_A1 + 3 * EE_A2 * t2 + t6 * (7 * EE_A3 + 9 * EE_A4 * t2);
  return [lon * Math.cos(theta) / (EE_M * polyX), theta * polyY];
}

function orthoXY(lon, lat, lon0, lat0) {
  const λ = lon - lon0;
  const cosc = Math.sin(lat0) * Math.sin(lat) + Math.cos(lat0) * Math.cos(lat) * Math.cos(λ);
  const x = Math.cos(lat) * Math.sin(λ);
  const y = Math.cos(lat0) * Math.sin(lat) - Math.sin(lat0) * Math.cos(lat) * Math.cos(λ);
  return [x, y, cosc];
}

function mercScale(lat) { return 1 / Math.cos(lat); }

function projectionMetrics(kind, lon, lat, lon0 = 0, lat0 = 0) {
  if (kind === "globe") {
    const c = orthoXY(lon, lat, lon0, lat0)[2];
    return c > 1e-8 ? {area:c, shape:1/c} : {area:NaN, shape:NaN};
  }
  if (kind === "mercator") {
    if (Math.abs(lat) >= MERC_MAX) return {area:NaN, shape:NaN};
    return {area:mercScale(lat)**2, shape:1};
  }
  const lambda=wrapPi(lon-lon0), t=Math.asin(EE_M*Math.sin(lat));
  const t2=t*t, t6=t2*t2*t2;
  const D=EE_A1+3*EE_A2*t2+7*EE_A3*t6+9*EE_A4*t6*t2;
  const dD=6*EE_A2*t+42*EE_A3*t**5+72*EE_A4*t**7;
  const dt=EE_M*Math.cos(lat)/Math.cos(t);
  const a=Math.cos(t)/(EE_M*D*Math.cos(lat));
  const b=lambda*(-Math.sin(t)*D-Math.cos(t)*dD)*dt/(EE_M*D*D);
  const d=D*dt, determinant=Math.abs(a*d), trace=a*a+b*b+d*d;
  const lmax=(trace+Math.sqrt(Math.max(0,trace*trace-4*determinant*determinant)))/2;
  return {area:determinant, shape:lmax/determinant};
}

// Clip sampled spherical-disk polygons in unwrapped longitude/latitude.
// Intersections follow polygon edges; no synthetic ellipse replaces a disk.
function clipAxis(poly, axis, limit, keepGreater) {
  const out=[];
  if (!poly.length) return out;
  const inside=p=>keepGreater?p[axis]>=limit:p[axis]<=limit;
  let a=poly[poly.length-1], ain=inside(a);
  for(const b of poly){
    const bin=inside(b);
    if(ain!==bin){const t=(limit-a[axis])/(b[axis]-a[axis]);out.push(a.map((v,j)=>v+t*(b[j]-v)));}
    if(bin)out.push(b);
    a=b;ain=bin;
  }
  return out;
}
function mapDiskParts(ring, centerLon, lon0, mercator) {
  const ref=wrapPi(centerLon-lon0);
  const unwrapped=ring.map(q=>[ref+wrapPi(q.lon-lon0-ref),q.lat]);
  const result=[];
  for(const shift of [-TAU,0,TAU]){
    let part=unwrapped.map(q=>[q[0]+shift,q[1]]);
    part=clipAxis(part,0,-Math.PI,true);part=clipAxis(part,0,Math.PI,false);
    if(mercator){part=clipAxis(part,1,-MERC_MAX,true);part=clipAxis(part,1,MERC_MAX,false);}
    if(part.length>=3)result.push(part);
  }
  return result;
}

function ease(t) {
  return t < 0.5 ? 16 * t * t * t * t * t : 1 - ((-2 * t + 2) ** 5) / 2;
}

function hexToRgb(h) {
  return [parseInt(h.slice(1, 3), 16), parseInt(h.slice(3, 5), 16), parseInt(h.slice(5, 7), 16)];
}

const pts = fibonacci(N);
const disks = pts.map(p => disk(p.lat, p.lon, ANG, SEGS));

const METHODS = ["globe", "mercator", "equalearth"];

function I() {
  const app = document.getElementById("app");
  const stage = document.getElementById("stage");
  const canvas = document.getElementById("field");
  const ctx = canvas.getContext("2d", { alpha: true });
  const plate = document.getElementById("plate");
  const pctx = plate.getContext("2d");
  const loader = document.getElementById("loader");
  const reduced = window.matchMedia("(prefers-reduced-motion: reduce)");

  let theme = "uv";
  let method = "globe";
  let split = false;
  let showScale = false;
  let showBand = false;
  let lockPin = false;
  let pin = -1;
  let hover = -1;
  let bandLat = 0;
  const bandHalf = 8 * RAD;

  let lon0 = 20 * RAD, lat0 = 8 * RAD;
  let vLon = 0, vLat = 0;
  let dragging = false, lx = 0, ly = 0, lt = 0;
  let mix = 1, pulse = 0, morphing = false, morphFrom = 0, morphT0 = 0;
  let prevMethod = "globe";
  const DUR = 1400;

  let W = 1, H = 1, PR = 1;
  const layouts = { globe: null, mercator: null, equalearth: null };
  let pointer = { x: 0, y: 0 };

  const css = () => getComputedStyle(app);

  function setTheme(next) {
    theme = next;
    app.className = "same-earth theme-" + theme + (split ? " is-split" : "");
    document.getElementById("paperLabel").classList.toggle("is-active", theme === "paper");
    document.getElementById("uvLabel").classList.toggle("is-active", theme === "uv");
    drawPlate();
  }

  function readColors() {
    const s = css();
    return {
      field: s.getPropertyValue("--field").trim(),
      ink: s.getPropertyValue("--ink").trim(),
      muted: s.getPropertyValue("--ink-muted").trim(),
      faint: s.getPropertyValue("--ink-faint").trim(),
      rule: s.getPropertyValue("--rule").trim(),
      accent: s.getPropertyValue("--accent").trim(),
      summary: s.getPropertyValue("--summary").trim(),
      warm: s.getPropertyValue("--warm").trim(),
      alert: s.getPropertyValue("--alert").trim(),
      land: s.getPropertyValue("--land").trim(),
      ocean: s.getPropertyValue("--ocean").trim(),
      landInk: s.getPropertyValue("--land-ink").trim()
    };
  }

  function fitRect(left, top, w, h, pad) {
    return { x: left + pad, y: top + pad, w: w - pad * 2, h: h - pad * 2 };
  }

  function layoutGlobe(rect, L0, B0) {
    const R=Math.min(rect.w,rect.h)*.46, cx=rect.x+rect.w*.5, cy=rect.y+rect.h*.48;
    const items=pts.map((p,i)=>{
      const camera=disks[i].map(q=>orthoXY(q.lon,q.lat,L0,B0));
      const clipped=clipAxis(camera,2,0,true).map(q=>{
        const norm=Math.hypot(...q)||1;return [cx+R*q[0]/norm,cy-R*q[1]/norm];
      });
      const [x,y,z]=orthoXY(p.lon,p.lat,L0,B0), metrics=projectionMetrics("globe",p.lon,p.lat,L0,B0);
      const poly=clipped.flat();
      return {x:cx+R*x,y:cy-R*y,z,visible:poly.length>=6,poly,parts:poly.length>=6?[poly]:[],...metrics};
    });
    return {kind:"globe",cx,cy,R,items,rect};
  }

  function layoutMap(kind, rect, L0 = 0) {
    const isM=kind==="mercator", project=isM?mercatorXY:equalEarthXY;
    const maxx=isM?Math.PI:equalEarthXY(Math.PI,0)[0];
    const maxy=isM?mercatorXY(0,MERC_MAX)[1]:equalEarthXY(0,Math.PI/2)[1];
    const minx=-maxx,miny=-maxy;
    // Fixed full-domain fit: camera changes cannot rescale one map independently.
    const scale=Math.min(rect.w/(2*maxx),Math.max(20,rect.h-38)/(2*maxy))*.94;
    const ox=rect.x+(rect.w-2*maxx*scale)/2, oy=rect.y+(rect.h-38-2*maxy*scale)/2;
    const toP=q=>[ox+(q[0]-minx)*scale,oy+(maxy-q[1])*scale];
    const items=pts.map((p,i)=>{
      const parts=mapDiskParts(disks[i],p.lon,L0,isM).map(part=>part.flatMap(q=>toP(project(q[0],q[1]))));
      const [x,y]=toP(project(wrapPi(p.lon-L0),p.lat));
      const metrics=projectionMetrics(kind,p.lon,p.lat,L0);
      return {x,y,z:p.lat,visible:parts.length>0,parts,poly:parts[0]||[],...metrics};
    });
    return {kind,items,rect,box:{ox,oy,s:scale,minx,maxx,miny,maxy}};
  }

  function viewRects() {
    if(W<=700){
      if(split){const h=(H-24)/2;return [{mode:"mercator",rect:{x:14,y:4,w:W-28,h}}, {mode:"equalearth",rect:{x:14,y:h+16,w:W-28,h}}];}
      return [{mode:method,rect:{x:12,y:8,w:W-24,h:H-16}}];
    }
    const top = Math.min(H * 0.10, 88);
    const bot = Math.min(H * 0.22, 188);
    const right = Math.min(W * 0.28, 340);
    if (split) {
      const left = Math.min(W * 0.03, 24);
      const gap = 36;
      const usable = W - left - right;
      const mid = (usable - gap) / 2;
      const topSplit = Math.min(H * 0.20, 168);
      return [
        { mode: "mercator", rect: fitRect(left, topSplit, mid, H - topSplit - bot, 8) },
        { mode: "equalearth", rect: fitRect(left + mid + gap, topSplit, mid, H - topSplit - bot, 8) }
      ];
    }
    if (method === "globe") {
      const left = Math.min(W * 0.20, 260);
      return [{ mode: method, rect: fitRect(left, top, W - left - right * 0.35, H - top - bot, 6) }];
    }
    const left = Math.min(W * 0.22, 300);
    return [{ mode: method, rect: fitRect(left, top + 8, W - left - right * 0.22, H - top - bot, 8) }];
  }

  let layoutKey = "";
  function rebuild(force) {
    const views = viewRects();
    const key = [W, H, method, split ? 1 : 0, morphing ? prevMethod : "", lon0.toFixed(3), (method === "globe" && !split ? lat0.toFixed(3) : "0")].join("|");
    if (!force && key === layoutKey && layouts[method]) return;
    layoutKey = key;
    if (split) {
      layouts.mercator = layoutMap("mercator", views[0].rect, lon0);
      layouts.equalearth = layoutMap("equalearth", views[1].rect, lon0);
    } else if (method === "globe") {
      layouts.globe = layoutGlobe(views[0].rect, lon0, lat0);
      if (morphing) layouts[prevMethod] = prevMethod === "globe" ? layouts.globe : layoutMap(prevMethod, views[0].rect, lon0);
    } else {
      layouts[method] = layoutMap(method, views[0].rect, lon0);
      if (morphing) {
        layouts[prevMethod] = prevMethod === "globe"
          ? layoutGlobe(views[0].rect, lon0, lat0)
          : layoutMap(prevMethod, views[0].rect, lon0);
      }
    }
  }

  function areaOf(m, i) { return projectionMetrics(m,pts[i].lon,pts[i].lat,lon0,lat0).area; }

  function lerpPoly(a, b, t) {
    const n = Math.min(a.length, b.length);
    const o = new Array(n);
    for (let i = 0; i < n; i++) o[i] = a[i] + (b[i] - a[i]) * t;
    return o;
  }

  function drawDiskPath(c, poly) {
    if (poly.length < 6) return;
    c.beginPath();
    c.moveTo(poly[0], poly[1]);
    for (let i = 2; i < poly.length; i += 2) c.lineTo(poly[i], poly[i + 1]);
    c.closePath();
  }

  function pickColor(col, i, area, inBand, alpha) {
    const land = pts[i].land;
    const base = land ? hexToRgb(col.land) : hexToRgb(col.ocean);
    const hot = hexToRgb(col.alert);
    const acc = hexToRgb(col.accent);
    let r = base[0], g = base[1], b = base[2];
    if (showScale && area > 1.05) {
      const t = Math.min(1, (Math.log(area) / Math.log(12)));
      r = r + (hot[0] - r) * t;
      g = g + (hot[1] - g) * t;
      b = b + (hot[2] - b) * t;
    }
    if (inBand) {
      r = r + (hexToRgb(col.summary)[0] - r) * 0.55;
      g = g + (hexToRgb(col.summary)[1] - g) * 0.55;
      b = b + (hexToRgb(col.summary)[2] - b) * 0.55;
    }
    if (i === pin || i === hover) {
      r = r + (acc[0] - r) * 0.42;
      g = g + (acc[1] - g) * 0.42;
      b = b + (acc[2] - b) * 0.42;
    }
    return `rgba(${r | 0},${g | 0},${b | 0},${alpha})`;
  }

  function inBand(i) {
    return showBand && Math.abs(pts[i].lat - bandLat) <= bandHalf;
  }

  function drawView(c, mode, layout, tMix, other, clipRect) {
    const col = readColors();
    const items = layout.items;
    const order = items.map((_, i) => i);
    if (mode === "globe") order.sort((a, b) => items[a].z - items[b].z);

    c.save();
    c.globalAlpha=tMix;
    if (clipRect) {
      c.beginPath();
      c.rect(clipRect.x, clipRect.y, clipRect.w, clipRect.h);
      c.clip();
    }

    if (mode === "globe") {
      c.save();
      c.beginPath();
      c.arc(layout.cx, layout.cy, layout.R, 0, TAU);
      c.fillStyle = theme === "uv" ? "rgba(18,16,34,0.35)" : "rgba(245,239,228,0.28)";
      c.fill();
      c.strokeStyle = col.rule;
      c.lineWidth = 1;
      c.stroke();
      // equator + meridians
      c.globalAlpha = 0.35*tMix;
      c.strokeStyle = col.faint;
      c.lineWidth = 0.7;
      for (const lat of [-60, -30, 0, 30, 60].map(d => d * RAD)) {
        c.beginPath();
        let started = false;
        for (let k = 0; k <= 64; k++) {
          const lon = -Math.PI + k / 64 * TAU;
          const [x, y, vis] = orthoXY(lon, lat, lon0, lat0);
          if (vis <= 0) { started = false; continue; }
          const px = layout.cx + x * layout.R, py = layout.cy - y * layout.R;
          if (!started) { c.moveTo(px, py); started = true; } else c.lineTo(px, py);
        }
        c.stroke();
      }
      c.restore();
    }

    const paint = (i) => {
      const it = items[i];
      const visible=it.visible, area=it.area;
      if (!visible) return;
      const facing = mode === "globe" ? 0.34 + 0.66 * Math.max(0, Math.min(1, (it.z + 0.08) / 1.08)) : 1;
      const land = pts[i].land;
      const a = land ? facing * (theme === "uv" ? 0.96 : 0.92) : facing * (theme === "uv" ? 0.16 : 0.22);
      c.fillStyle = pickColor(col, i, area, inBand(i), a);
      c.beginPath();
      for(const part of it.parts){
        if(part.length<6)continue;c.moveTo(part[0],part[1]);
        for(let k=2;k<part.length;k+=2)c.lineTo(part[k],part[k+1]);c.closePath();
      }
      c.fill();
      if (i === pin || i === hover || inBand(i)) {
        c.strokeStyle = i === pin ? col.accent : inBand(i) ? col.summary : col.warm;
        c.lineWidth = i === pin ? 1.7 : 1;
        c.globalAlpha = 0.95*tMix;
        c.stroke();
        c.globalAlpha = tMix;
      }
    };
    for (const i of order) if (!pts[i].land) paint(i);
    for (const i of order) if (pts[i].land) paint(i);
    c.restore();
  }

  function drawLabels(c, views) {
    const col = readColors();
    c.font = "12px ui-monospace, SFMono-Regular, Menlo, Consolas, monospace";
    c.fillStyle = col.faint;
    c.textBaseline = "top";
    if (split || method !== "globe") {
      views.forEach((v) => {
        const label = v.mode === "globe" ? "01  GLOBE" : v.mode === "mercator" ? "02  MERCATOR" : "03  EQUAL EARTH";
        c.fillText(label, v.rect.x + 10, v.rect.y + v.rect.h - 28);
        if (split) {
          const sub = v.mode === "mercator" ? "local angles held · polar caps clipped" : "local area held · shape changes";
          c.fillText(sub, v.rect.x + 10, v.rect.y + v.rect.h - 16);
        }
      });
    }
  }

  function drawBandGuides(c, views) {
    if (!showBand) return;
    const col = readColors();
    c.save();
    c.strokeStyle = col.summary;
    c.globalAlpha = 0.35;
    c.setLineDash([3, 5]);
    for (const v of views) {
      const L = layouts[v.mode];
      if (!L) continue;
      c.beginPath();
      if (v.mode === "globe") {
        let started = false;
        for (let k = 0; k <= 80; k++) {
          const lon = -Math.PI + k / 80 * TAU;
          const [x, y, vis] = orthoXY(lon, bandLat, lon0, lat0);
          if (vis <= 0) { started = false; continue; }
          const px = L.cx + x * L.R, py = L.cy - y * L.R;
          if (!started) { c.moveTo(px, py); started = true; } else c.lineTo(px, py);
        }
      } else if (L.box) {
        const b = L.box;
        const isM = v.mode === "mercator";
        for (let k = 0; k <= 64; k++) {
          const lon = -Math.PI + k / 64 * TAU;
          const xy = isM ? mercatorXY(lon, bandLat) : equalEarthXY(lon, bandLat);
          const px = b.ox + (xy[0] - b.minx) * b.s;
          const py = b.oy + (b.maxy - xy[1]) * b.s;
          if (k === 0) c.moveTo(px, py); else c.lineTo(px, py);
        }
      }
      c.stroke();
    }
    c.restore();
  }

  function currentFocus() {
    return pin >= 0 ? pin : hover >= 0 ? hover : nearestToLat(bandLat);
  }

  function nearestToLat(lat) {
    let best = 0, d = 1e9;
    for (let i = 0; i < N; i++) {
      const e = Math.abs(pts[i].lat - lat) + Math.abs(pts[i].lon) * 0.15;
      if (e < d) { d = e; best = i; }
    }
    return best;
  }

  function updateReadout() {
    const i=currentFocus(), p=pts[i], metrics=projectionMetrics(method,p.lon,p.lat,lon0,lat0);
    const fmt=v=>Number.isFinite(v)?v.toFixed(2):"outside view";
    document.getElementById("statScale").textContent=morphing?"—":fmt(metrics.area);
    document.getElementById("statShape").textContent=morphing?"—":fmt(metrics.shape);
    document.getElementById("statScale").parentElement.hidden=split;
    document.getElementById("statShape").parentElement.hidden=split;
    document.getElementById("statLat").textContent=(p.lat*DEG).toFixed(1)+"°";
    document.getElementById("statPin").textContent=pin>=0?`${(p.lon*DEG).toFixed(1)}° lon`:hover>=0?"hover":"band focus";
    document.getElementById("splitReadout").hidden=!split;
    for(const [key,kind] of [["merc","mercator"],["equal","equalearth"]]){
      const m=projectionMetrics(kind,p.lon,p.lat,lon0,lat0);
      document.getElementById(key+"Area").textContent=fmt(m.area);
      document.getElementById(key+"Shape").textContent=fmt(m.shape);
    }
    document.getElementById("measureScope").textContent=morphing?"Presentation crossfade · measurements resume when settled":
      split?"Same location · local scale before each map is fitted to its panel":
      method==="globe"?"Orthographic view scale · the spherical surface stays unchanged":
      method==="mercator"?"Local map scale · clipped at ±85.05113° latitude":"Local map scale · before fitting to the panel";
  }

  function applyMeta() {
    const key = split ? "mercator" : method;
    const e = META[method];
    document.getElementById("methodIndex").textContent = split ? "02·03" : e.index;
    document.getElementById("methodName").textContent = split ? "Split field" : e.name;
    document.getElementById("methodClaim").textContent = split ? "Shape vs area" : e.claim;
    document.getElementById("methodNote").textContent = split
      ? "Same disks, two claims. Mercator grows toward the poles. Equal Earth keeps area and spends shape."
      : e.note;
    document.getElementById("plateTitle").textContent = split ? "Fig. 02·03 — two claims" : e.plateTitle;
    document.getElementById("plateKey").textContent = split ? "shared samples" : e.plateKey;
    document.getElementById("plateCaption").textContent = split ? "Local area scale versus latitude." : e.plateCaption;
    document.getElementById("plateSide").textContent = split ? "side by side" : e.plateSide;
    document.getElementById("dragNote").textContent = method === "globe" && !split ? "Drag to turn" : "Drag a band · click a disk";
    document.querySelectorAll(".method-nav button").forEach(btn => {
      btn.classList.toggle("is-active", !split && btn.dataset.method === method);
      btn.setAttribute("aria-pressed", (!split && btn.dataset.method === method) ? "true" : "false");
    });
    const live = split
      ? "Split field. Mercator beside Equal Earth. Same 1536 geodesic disks."
      : `${e.name} selected. ${e.claim}.`;
    app.className = "same-earth theme-" + theme + (split ? " is-split" : "");
    document.getElementById("live").textContent = live;
    document.getElementById("splitBtn").classList.toggle("is-active",split);
    document.getElementById("splitBtn").setAttribute("aria-pressed",String(split));
    updateReadout();
    drawPlate();
  }

  function startMorph(next) {
    if (next === method && !split) return;
    prevMethod = split ? "mercator" : method;
    method = next;
    split = false;
    if (reduced.matches) { mix = 1; morphing = false; applyMeta(); return; }
    morphing = true;
    morphT0 = performance.now();
    mix = 0;
    applyMeta();
  }

  function drawPlate() {
    const col = readColors();
    const w = plate.width, h = plate.height;
    pctx.clearRect(0, 0, w, h);
    pctx.fillStyle = theme === "uv" ? "#171329" : "#F5EFE4";
    pctx.fillRect(0, 0, w, h);
    pctx.strokeStyle = theme === "uv" ? "rgba(77,70,114,0.55)" : "rgba(128,111,100,0.38)";
    pctx.strokeRect(0.5, 0.5, w - 1, h - 1);
    pctx.font = "9px ui-monospace, monospace";
    pctx.fillStyle = col.faint;

    const i = currentFocus();
    const lat = pts[i].lat;
    const xs = 36, xe = w - 20, yb = h - 28, yt = 22;
    const xAt = φ => xs + (φ + Math.PI / 2) / Math.PI * (xe - xs);
    const yAt = v => yb - Math.min(v, 8) / 8 * (yb - yt);

    pctx.strokeStyle = col.rule;
    pctx.beginPath();
    pctx.moveTo(xs, yt); pctx.lineTo(xs, yb); pctx.lineTo(xe, yb);
    pctx.stroke();

    // sec^2 curve (mercator area) and unit area
    pctx.beginPath();
    pctx.strokeStyle = col.alert;
    pctx.lineWidth = 1.4;
    for (let k = 0; k <= 80; k++) {
      const φ = -MERC_MAX + k / 80 * (2 * MERC_MAX);
      const v = mercScale(φ) ** 2;
      const x = xAt(φ), y = yAt(v);
      if (k === 0) pctx.moveTo(x, y); else pctx.lineTo(x, y);
    }
    pctx.stroke();
    pctx.beginPath();
    pctx.strokeStyle = col.summary;
    pctx.setLineDash([]);
    pctx.moveTo(xAt(-Math.PI / 2), yAt(1));
    pctx.lineTo(xAt(Math.PI / 2), yAt(1));
    pctx.stroke();

    const xf = xAt(lat);
    pctx.strokeStyle = col.accent;
    pctx.beginPath();
    pctx.moveTo(xf, yt);
    pctx.lineTo(xf, yb);
    pctx.stroke();
    pctx.fillStyle = col.muted;
    pctx.fillText("local area × (clipped at 8)", xs + 6, 12);
    pctx.fillText("−90", xs - 4, h - 14);
    pctx.fillText("0", (xs + xe) / 2 - 4, h - 14);
    pctx.fillText("+90", xe - 18, h - 14);
    pctx.fillStyle = col.alert;
    pctx.fillText("Mercator sec²φ", xe - 108, 12);
    pctx.fillStyle = col.summary;
    pctx.fillText("Equal Earth 1", xe - 108, 24);
  }

  function hitTest(mx, my) {
    const views = viewRects();
    let best = -1, bd = 22;
    for (const v of views) {
      const lay = layouts[v.mode];
      if (!lay) continue;
      for (let i = 0; i < N; i++) {
        const it = lay.items[i];
        if (!it.visible) continue;
        const dx = it.x - mx, dy = it.y - my;
        const rad = Math.max(6, Math.min(it.rw, it.rh));
        const d = Math.hypot(dx, dy);
        if (d < rad + 4 && d < bd) { bd = d; best = i; }
      }
    }
    return best;
  }

  function resize() {
    const r = stage.getBoundingClientRect();
    W = Math.max(1, Math.round(r.width));
    H = Math.max(1, Math.round(r.height));
    PR = Math.min(window.devicePixelRatio || 1, 2);
    canvas.width = Math.floor(W * PR);
    canvas.height = Math.floor(H * PR);
    canvas.style.width = W + "px";
    canvas.style.height = H + "px";
    ctx.setTransform(PR, 0, 0, PR, 0, 0);
    rebuild(true);
  }

  function frame(now) {
    try {
      if (morphing) {
        const t = Math.min(1, (now - morphT0) / DUR);
        mix = ease(t);
        pulse = Math.sin(Math.PI * t);
        if (t >= 1) { morphing = false; mix = 1; pulse = 0; }
      }
      if (!dragging && method === "globe" && !split && !reduced.matches) {
        if (lockPin && pin >= 0) {
          const tlon = pts[pin].lon, tlat = pts[pin].lat;
          lon0 += wrapPi(tlon - lon0) * 0.06;
          lat0 += (tlat - lat0) * 0.06;
        } else {
          lon0 += vLon + 0.00018;
          lat0 = Math.max(-1.05, Math.min(1.05, lat0 + vLat));
          vLon *= 0.92;
          vLat *= 0.92;
        }
      }
      rebuild();
      ctx.clearRect(0, 0, W, H);
      const views = viewRects();
      if (split) {
        drawView(ctx, "mercator", layouts.mercator, 1, null, views[0].rect);
        drawView(ctx, "equalearth", layouts.equalearth, 1, null, views[1].rect);
      } else if (morphing && layouts[prevMethod] && layouts[method]) {
        drawView(ctx, prevMethod, layouts[prevMethod], 1-mix, null, views[0].rect);
        drawView(ctx, method, layouts[method], mix, null, views[0].rect);
      } else {
        drawView(ctx, method, layouts[method], 1, null, views[0].rect);
      }
      drawBandGuides(ctx, views);
      drawLabels(ctx, views);
      updateReadout();
      if (loader && !loader.classList.contains("is-hidden")) loader.classList.add("is-hidden");
    } catch (err) {
      console.error(err);
    }
    requestAnimationFrame(frame);
  }

  function uiFromEvent(e) {
    const r = canvas.getBoundingClientRect();
    return { x: e.clientX - r.left, y: e.clientY - r.top };
  }

  function overChrome(el) {
    return !!el.closest?.(".use-plate, .method-nav, .study-tools, .theme-switch, .series-chip, .study-registration, .study-header, a");
  }

  stage.addEventListener("pointerdown", e => {
    if (e.button !== 0 || overChrome(e.target)) return;
    const p = uiFromEvent(e);
    const hit = hitTest(p.x, p.y);
    if (hit >= 0) {
      pin = pin === hit ? -1 : hit;
      if (pin >= 0) bandLat = pts[pin].lat;
      applyMeta();
    }
    dragging = true;
    lx = e.clientX; ly = e.clientY; lt = performance.now();
    stage.setPointerCapture(e.pointerId);
    stage.dataset.dragging = "true";
  });

  stage.addEventListener("pointermove", e => {
    const p = uiFromEvent(e);
    pointer = p;
    hover = hitTest(p.x, p.y);
    if (showBand && !dragging) {
      // hover lat from nearest
      if (hover >= 0) { /* readout only */ }
    }
    if (!dragging) return;
    e.preventDefault();
    const now = performance.now();
    const dx = e.clientX - lx, dy = e.clientY - ly;
    if (method === "globe" && !split) {
      const dt = Math.max(8, now - lt);
      lon0 -= dx * 0.005;
      lat0 = Math.max(-1.15, Math.min(1.15, lat0 + dy * 0.0045));
      vLon = -dx / dt * 16 * 0.005;
      vLat = dy / dt * 16 * 0.0045;
    } else {
      lon0 = wrapPi(lon0 - dx * 0.005);
      bandLat = Math.max(-80 * RAD, Math.min(80 * RAD, bandLat - dy * 0.004));
      showBand = true;
      document.getElementById("bandBtn").classList.add("is-active");
      document.getElementById("bandBtn").setAttribute("aria-pressed", "true");
      document.getElementById("bandKey").classList.add("is-visible");
    }
    lx = e.clientX; ly = e.clientY; lt = now;
  });

  const endDrag = e => {
    if (!dragging) return;
    dragging = false;
    delete stage.dataset.dragging;
    if (stage.hasPointerCapture(e.pointerId)) stage.releasePointerCapture(e.pointerId);
  };
  stage.addEventListener("pointerup", endDrag);
  stage.addEventListener("pointercancel", endDrag);

  document.getElementById("themeBtn").addEventListener("click", () => setTheme(theme === "uv" ? "paper" : "uv"));
  document.querySelectorAll(".method-nav button").forEach(btn => {
    btn.addEventListener("click", () => startMorph(btn.dataset.method));
  });
  document.getElementById("scaleBtn").addEventListener("click", () => {
    showScale = !showScale;
    document.getElementById("scaleBtn").classList.toggle("is-active", showScale);
    document.getElementById("scaleBtn").setAttribute("aria-pressed", showScale ? "true" : "false");
    document.getElementById("scaleKey").classList.toggle("is-visible", showScale);
    document.getElementById("scaleKey").setAttribute("aria-hidden", showScale ? "false" : "true");
  });
  document.getElementById("bandBtn").addEventListener("click", () => {
    showBand = !showBand;
    document.getElementById("bandBtn").classList.toggle("is-active", showBand);
    document.getElementById("bandBtn").setAttribute("aria-pressed", showBand ? "true" : "false");
    document.getElementById("bandKey").classList.toggle("is-visible", showBand);
    document.getElementById("bandKey").setAttribute("aria-hidden", showBand ? "false" : "true");
  });
  document.getElementById("splitBtn").addEventListener("click", () => {
    split = !split;
    if (split) { prevMethod = method; method = "mercator"; mix = 1; morphing = false; }
    document.getElementById("splitBtn").classList.toggle("is-active", split);
    document.getElementById("splitBtn").setAttribute("aria-pressed", split ? "true" : "false");
    applyMeta();
  });
  document.getElementById("lockBtn").addEventListener("click", () => {
    lockPin = !lockPin;
    if (lockPin && pin < 0) pin = hover >= 0 ? hover : nearestToLat(20 * RAD);
    document.getElementById("lockBtn").classList.toggle("is-active", lockPin);
    document.getElementById("lockBtn").setAttribute("aria-pressed", lockPin ? "true" : "false");
    applyMeta();
  });

  window.addEventListener("keydown", e => {
    if (e.altKey || e.ctrlKey || e.metaKey) return;
    if (e.key === "1") startMorph("globe");
    if (e.key === "2") startMorph("mercator");
    if (e.key === "3") startMorph("equalearth");
    if (e.key.toLowerCase() === "t") document.getElementById("themeBtn").click();
    if (e.key.toLowerCase() === "s") document.getElementById("splitBtn").click();
    if (e.key.toLowerCase() === "p") document.getElementById("scaleBtn").click();
    if (e.key.toLowerCase() === "b") document.getElementById("bandBtn").click();
    if (e.key.toLowerCase() === "l") document.getElementById("lockBtn").click();
    if (e.key === "[" || e.key === "]") {
      showBand = true;
      bandLat += (e.key === "]" ? 1 : -1) * 4 * RAD;
      bandLat = Math.max(-80 * RAD, Math.min(80 * RAD, bandLat));
      document.getElementById("bandBtn").classList.add("is-active");
      document.getElementById("bandKey").classList.add("is-visible");
    }
    if (e.key === "Escape") { pin = -1; lockPin = false; document.getElementById("lockBtn").classList.remove("is-active");document.getElementById("lockBtn").setAttribute("aria-pressed","false"); }
  });

  const plateEl = document.getElementById("usePlate");
  const inspect = on => plateEl.classList.toggle("is-inspecting", on);
  plateEl.addEventListener("pointerenter", () => inspect(true));
  plateEl.addEventListener("pointerleave", () => inspect(false));

  new ResizeObserver(resize).observe(stage);
  resize();
  applyMeta();
  let boot = (location.hash || "").replace("#","");
  if (boot === "mollweide") boot = "equalearth";
  if (boot === "mercator" || boot === "equalearth" || boot === "globe") startMorph(boot);
  if (boot === "split") { split = true; method = "mercator"; applyMeta(); document.getElementById("splitBtn").classList.add("is-active");document.getElementById("splitBtn").setAttribute("aria-pressed","true"); }
  if (boot === "paper") setTheme("paper");
  requestAnimationFrame(frame);
}

I();
  